import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import type { ITodoListTodolistmember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodolistmember";

/**
 * Validate todo creation by authenticated todoListMember.
 *
 * This test covers all business rules for the creation of todos:
 *
 * - Register and authenticate a unique user
 * - Successfully create todos with:
 *
 *   - Minimum and maximum length titles/description
 *   - Various is_complete statuses
 * - Confirm API enforces:
 *
 *   - Title uniqueness per user
 *   - Required (non-blank) title
 *   - Optional and nullable description
 *   - Is_complete correct propagation
 * - Check for failure when using duplicate title, blank title, or creating
 *   unauthenticated.
 * - Ensure response matches ITodoListTodo contract.
 */
export async function test_api_todo_creation_by_member(
  connection: api.IConnection,
) {
  // 1. Register & authenticate a new todoListMember
  const email: string = typia.random<string & tags.Format<"email">>();
  const password: string = RandomGenerator.alphabets(10);
  const joinBody = {
    email,
    password,
    href: "https://client.example.com/signup",
    referrer: "https://client.example.com/landing",
  } satisfies ITodoListTodolistmember.ICreate;
  const member: ITodoListTodolistmember.IAuthorized =
    await api.functional.auth.todoListMember.join(connection, {
      body: joinBody,
    });
  typia.assert(member);
  TestValidator.equals(
    "auth email matches input",
    member.email,
    joinBody.email,
  );

  // 2. Create todo with minimum field lengths
  const minTitle = "a"; // 1 char, MinLength=1
  const todoMin: ITodoListTodo =
    await api.functional.todoList.todoListMember.todos.create(connection, {
      body: {
        title: minTitle,
        is_complete: false,
      } satisfies ITodoListTodo.ICreate,
    });
  typia.assert(todoMin);
  TestValidator.equals("min title matches", todoMin.title, minTitle);
  TestValidator.equals("is_complete false", todoMin.is_complete, false);
  TestValidator.equals(
    "description omitted is undefined/null",
    todoMin.description,
    undefined,
  );

  // 3. Create todo with maximum allowed field lengths and completed status
  const maxTitle = RandomGenerator.alphabets(100);
  const maxDesc = RandomGenerator.alphabets(1000);
  const todoMax: ITodoListTodo =
    await api.functional.todoList.todoListMember.todos.create(connection, {
      body: {
        title: maxTitle,
        description: maxDesc,
        is_complete: true,
      } satisfies ITodoListTodo.ICreate,
    });
  typia.assert(todoMax);
  TestValidator.equals("max title matches", todoMax.title, maxTitle);
  TestValidator.equals("max desc matches", todoMax.description, maxDesc);
  TestValidator.equals("is_complete true", todoMax.is_complete, true);
  TestValidator.predicate(
    "completed_at present when complete",
    todoMax.completed_at !== null && todoMax.completed_at !== undefined,
  );

  // 4. Create todo with description explicitly set to null
  const nullDescTitle = RandomGenerator.paragraph({ sentences: 3, wordMin: 5 });
  const todoNullDesc: ITodoListTodo =
    await api.functional.todoList.todoListMember.todos.create(connection, {
      body: {
        title: nullDescTitle,
        description: null,
        is_complete: false,
      } satisfies ITodoListTodo.ICreate,
    });
  typia.assert(todoNullDesc);
  TestValidator.equals("description is null", todoNullDesc.description, null);

  // 5. Confirm per-user title uniqueness: fail with duplicate title
  await TestValidator.error("fail on duplicate title", async () => {
    await api.functional.todoList.todoListMember.todos.create(connection, {
      body: {
        title: minTitle,
        is_complete: false,
      } satisfies ITodoListTodo.ICreate,
    });
  });

  // 6. Confirm title must not be blank
  await TestValidator.error("fail on blank title", async () => {
    await api.functional.todoList.todoListMember.todos.create(connection, {
      body: {
        title: "",
        is_complete: false,
      } satisfies ITodoListTodo.ICreate,
    });
  });

  // 7. Unauthenticated creation attempt should fail
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("fail unauthenticated todo create", async () => {
    await api.functional.todoList.todoListMember.todos.create(unauthConn, {
      body: {
        title: RandomGenerator.name(2),
        is_complete: false,
      } satisfies ITodoListTodo.ICreate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListTodolistmember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodolistmember";

/**
 * Validates that an authenticated todoListMember can successfully update their
 * own email address immediately after registration.
 *
 * 1. Register a new todoListMember using valid, unique input
 * 2. Capture the member's initial profile (should include id, email, created_at)
 * 3. Generate a unique new email address for update
 * 4. Call self-update endpoint (/todoList/todoListMember/actors/me) to update the
 *    email
 * 5. Assert the response email is updated and id matches the authenticated user
 * 6. Attempt to update the email to an existing (already used) email, expect
 *    failure (uniqueness constraint)
 * 7. Confirm that authentication tokens/session are still valid after update (user
 *    can still perform self-queries)
 */
export async function test_api_todolistmember_update_email_after_registration(
  connection: api.IConnection,
) {
  // 1. Register new member
  const baseEmail: string = typia.random<string & tags.Format<"email">>();
  const basePassword: string = RandomGenerator.alphaNumeric(12);
  const registrationBody = {
    email: baseEmail,
    password: basePassword,
    href: "https://example.com/signup",
    referrer: "https://example.com/landing",
  } satisfies ITodoListTodolistmember.ICreate;
  const registered: ITodoListTodolistmember.IAuthorized =
    await api.functional.auth.todoListMember.join(connection, {
      body: registrationBody,
    });
  typia.assert(registered);

  // 2. Capture initial profile
  const initialId = registered.id;
  const initialEmail = registered.email;
  const initialCreatedAt = registered.created_at;
  TestValidator.equals(
    "response email matches registration",
    registered.email,
    baseEmail,
  );

  // 3. Generate a unique new email
  const updatedEmail: string = typia.random<string & tags.Format<"email">>();

  // 4. Self-update email
  const updateBody = {
    email: updatedEmail,
  } satisfies ITodoListTodolistmember.IUpdate;
  const updatedProfile: ITodoListTodolistmember =
    await api.functional.todoList.todoListMember.actors.me.update(connection, {
      body: updateBody,
    });
  typia.assert(updatedProfile);

  // 5. Validate updated email, id invariant, and created_at invariant
  TestValidator.equals(
    "updated email reflected in profile",
    updatedProfile.email,
    updatedEmail,
  );
  TestValidator.equals("user id is unchanged", updatedProfile.id, initialId);
  TestValidator.equals(
    "created_at is unchanged",
    updatedProfile.created_at,
    initialCreatedAt,
  );

  // 6. Attempt to update email to an existing email (should fail validation)
  await TestValidator.error(
    "should fail when updating to an already used email",
    async () => {
      await api.functional.todoList.todoListMember.actors.me.update(
        connection,
        {
          body: { email: baseEmail } satisfies ITodoListTodolistmember.IUpdate,
        },
      );
    },
  );

  // 7. Confirm authentication/session remains valid
  // Try self-update a second time with a new unique email
  const anotherEmail: string = typia.random<string & tags.Format<"email">>();
  const result2: ITodoListTodolistmember =
    await api.functional.todoList.todoListMember.actors.me.update(connection, {
      body: { email: anotherEmail } satisfies ITodoListTodolistmember.IUpdate,
    });
  typia.assert(result2);
  TestValidator.equals(
    "second email update works",
    result2.email,
    anotherEmail,
  );
  TestValidator.equals("session id invariant", result2.id, initialId);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import type { ITodoListTodolistmember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodolistmember";

/**
 * Validates permanent deletion of a todo by its owner.
 *
 * - Register and authenticate as a todoListMember
 * - Create a todo item
 * - Delete the created todo
 * - (Negative path) Try to delete by a different user (not implemented since only
 *   owner is authenticated in this flow)
 * - Confirm permanent removal (by business rules, no data should remain
 *   accessible, and only audit logs are left, which are not exposed via API)
 * - If attempted retrieval or second deletion is supported, confirm error is
 *   thrown
 */
export async function test_api_todo_deletion_by_owner(
  connection: api.IConnection,
) {
  // 1. Register and authenticate as a new todoListMember
  const memberInput = {
    email: typia.random<
      string & tags.MinLength<1> & tags.MaxLength<255> & tags.Format<"email">
    >(),
    password: RandomGenerator.alphaNumeric(12), // Length 12
    href: "https://test-todo.com/join",
    referrer: "https://test-todo.com/welcome",
    ip: "127.0.0.1",
  } satisfies ITodoListTodolistmember.ICreate;
  const member = await api.functional.auth.todoListMember.join(connection, {
    body: memberInput,
  });
  typia.assert(member);
  TestValidator.equals("registered email", member.email, memberInput.email);

  // 2. Create a new todo under authenticated user
  const todoInput = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 5, wordMax: 10 }),
    description: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 4,
      sentenceMax: 8,
      wordMin: 5,
      wordMax: 15,
    }),
    is_complete: false,
  } satisfies ITodoListTodo.ICreate;
  const todo = await api.functional.todoList.todoListMember.todos.create(
    connection,
    { body: todoInput },
  );
  typia.assert(todo);
  TestValidator.equals(
    "todo title after creation",
    todo.title,
    todoInput.title,
  );

  // 3. Permanently delete the created todo
  await api.functional.todoList.todoListMember.todos.erase(connection, {
    todoId: todo.id,
  });

  // 4. Attempt to delete again should fail (confirm permanence of deletion)
  await TestValidator.error("cannot delete already deleted todo", async () => {
    await api.functional.todoList.todoListMember.todos.erase(connection, {
      todoId: todo.id,
    });
  });
}

