import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodolistmember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodolistmember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthTodoListMemberRefresh(props: {
  body: ITodoListTodolistmember.IRefresh;
}): Promise<ITodoListTodolistmember.IAuthorized> {
  let decoded: { id: string; session_id: string; type: string };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as { id: string; session_id: string; type: string };
  } catch (_err) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (decoded.type !== "todolistmember") {
    throw new HttpException("Invalid token type for todoListMember", 403);
  }

  const session =
    await MyGlobal.prisma.todo_list_todolistmember_sessions.findFirst({
      where: {
        id: decoded.session_id,
        todo_list_todolistmember_id: decoded.id,
      },
    });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }
  if (
    session.expired_at &&
    new Date(session.expired_at).getTime() < Date.now()
  ) {
    throw new HttpException("Session expired", 401);
  }

  // Now load member info
  const member = await MyGlobal.prisma.todo_list_todolistmembers.findUnique({
    where: { id: decoded.id },
  });
  if (!member) {
    throw new HttpException("Associated member not found", 401);
  }
  if ("deleted_at" in member && member.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }

  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const now = new Date();

  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: decoded.type,
        id: decoded.id,
        session_id: decoded.session_id,
        created_at: now.toISOString(),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: decoded.type,
        id: decoded.id,
        session_id: decoded.session_id,
        tokenType: "refresh",
        created_at: now.toISOString(),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  await MyGlobal.prisma.todo_list_todolistmember_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: toISOStringSafe(refreshExpires) },
  });

  return {
    id: member.id,
    email: member.email,
    created_at: toISOStringSafe(member.created_at),
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodo";
import { TodolistmemberPayload } from "../decorators/payload/TodolistmemberPayload";

export async function putTodoListTodoListMemberTodosTodoId(props: {
  todoListMember: TodolistmemberPayload;
  todoId: string & tags.Format<"uuid">;
  body: ITodoListTodo.IUpdate;
}): Promise<ITodoListTodo> {
  // 1. Find the todo and check ownership
  const todo = await MyGlobal.prisma.todo_list_todos.findUnique({
    where: {
      id: props.todoId,
      todo_list_todolistmember_id: props.todoListMember.id,
    },
  });
  if (!todo) {
    throw new HttpException("Todo not found", 404);
  }

  // 2. If updating the title, enforce uniqueness per-user
  if (props.body.title !== undefined && props.body.title !== todo.title) {
    const duplicate = await MyGlobal.prisma.todo_list_todos.findFirst({
      where: {
        title: props.body.title,
        todo_list_todolistmember_id: props.todoListMember.id,
        id: { not: props.todoId },
      },
    });
    if (duplicate) {
      throw new HttpException("Todo title must be unique per user", 409);
    }
  }

  // 3. Determine completed status/field
  let completed_at: (string & tags.Format<"date-time">) | null | undefined =
    todo.completed_at ? toISOStringSafe(todo.completed_at) : null;
  if (props.body.is_complete !== undefined) {
    if (props.body.is_complete && !todo.is_complete) {
      completed_at = toISOStringSafe(new Date());
    } else if (!props.body.is_complete) {
      completed_at = null;
    }
  }

  // 4. Update
  const updated = await MyGlobal.prisma.todo_list_todos.update({
    where: {
      id: props.todoId,
      todo_list_todolistmember_id: props.todoListMember.id,
    },
    data: {
      ...(props.body.title !== undefined && { title: props.body.title }),
      ...(props.body.description !== undefined && {
        description: props.body.description,
      }),
      ...(props.body.is_complete !== undefined && {
        is_complete: props.body.is_complete,
      }),
      completed_at,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  return {
    id: updated.id,
    title: updated.title,
    description: updated.description === null ? undefined : updated.description,
    is_complete: updated.is_complete,
    completed_at: updated.completed_at
      ? toISOStringSafe(updated.completed_at)
      : undefined,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoListTodolistmember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListTodolistmember";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthTodoListMemberLogin(props: {
  body: ITodoListTodolistmember.ILogin;
}): Promise<ITodoListTodolistmember.IAuthorized> {
  const { email, password, href, referrer, ip } = props.body;
  const member = await MyGlobal.prisma.todo_list_todolistmembers.findFirst({
    where: { email },
  });
  if (!member) {
    throw new HttpException("Invalid credentials", 401);
  }
  const valid = await PasswordUtil.verify(password, member.password_hash);
  if (!valid) {
    throw new HttpException("Invalid credentials", 401);
  }
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000);
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
  const sessionId = v4();

  const sessionData: any = {
    id: sessionId,
    todo_list_todolistmember_id: member.id,
    href,
    referrer,
    created_at: toISOStringSafe(now),
    expired_at: toISOStringSafe(accessExpires),
  };
  if (ip !== null && ip !== undefined)
    sessionData.ip = ip satisfies string as string;

  const session =
    await MyGlobal.prisma.todo_list_todolistmember_sessions.create({
      data: sessionData,
    });
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "todolistmember",
        id: member.id,
        session_id: session.id,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
